+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ * By default, the layout within the configured store folder will look like:
+ * <pre><code>
+ * storeFolder
+ *   |-- stored.rules (the index file of all stored rules)
+ *   |-- 6fc2fd04-b3ab-44e0-8f78-215c66f2174a (a rule violation file named randomly by UUID and referenced from stored.rules)
+ *   |-- 2186b43a-c24c-417d-bd96-547e2dfdba1c (another rule violation file)
+ *   |-- ... (more rule violation files for every rule that has been stored so far)
+ * </code></pre>
+ * To adjust the strategy how the individual rule violation files are named use the constructor
+ * {@link TextFileBasedViolationStore#TextFileBasedViolationStore(RuleViolationFileNameStrategy) TextFileBasedViolationStore(RuleViolationFileNameStrategy)}.<br>
+ * This {@link ViolationStore} can be configured through the following properties:
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=...          # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=...          # ignore, repair, or fail
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_DEFAULT = "ignore";
+
+    /* The lock deliberately covers both initialization and saves. A store must not inspect a half-written save. */
+    private static final ConcurrentHashMap<String, Object> LOCKS_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private IntegrityMode integrityMode;
+    private FileNameMode fileNameMode;
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private File storeFolder;
+    private Path storeFolderPath;
+    private Path storeFolderRealPath;
+    private Path storedRulesPath;
+    private String lockKey;
+    private Properties storedRules;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s
+     *
+     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new NullPointerException("ruleViolationFileNameStrategy");
+        }
+        constructorStrategy = ruleViolationFileNameStrategy;
+    }
+
+    @Override
+    public synchronized void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = parseIntegrity(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        configureFileNameStrategy(properties);
+
+        storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
+        storeFolderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        try {
+            lockKey = storeFolderPath.toFile().getCanonicalPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+
+        synchronized (lockFor(lockKey)) {
+            initializeUnderLock();
+        }
+    }
+
+    private void initializeUnderLock() {
+        storedRulesPath = storeFolderPath.resolve(STORED_RULES_FILE_NAME);
+        boolean indexWasAbsent = !pathExists(storedRulesPath);
+        if (indexWasAbsent && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        try {
+            Files.createDirectories(storeFolderPath);
+            storeFolderRealPath = storeFolderPath.toRealPath();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+
+        boolean indexCreated = false;
+        try {
+            if (indexWasAbsent) {
+                try {
+                    Files.createFile(storedRulesPath);
+                    indexCreated = true;
+                } catch (java.nio.file.FileAlreadyExistsException e) {
+                    // Another store in this process cannot get here while holding the lock, but this also handles
+                    // an index which appeared between the existence check and createFile.
+                    indexWasAbsent = false;
+                }
+            }
+            if (!isRegularDirectFile(storedRulesPath)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Violation store index must be a regular file directly in %s: %s", storeFolderPath, storedRulesPath));
+            }
+
+            Properties loaded = loadRulesFrom(storedRulesPath);
+            if (integrityMode != IntegrityMode.IGNORE) {
+                IntegrityScan scan = inspect(loaded);
+                if (integrityMode == IntegrityMode.FAIL) {
+                    if (scan.hasProblems()) {
+                        throw new StoreInitializationFailedException(scan.report());
+                    }
+                } else {
+                    if (!storeUpdateAllowed) {
+                        throw new StoreInitializationFailedException(String.format(
+                                "Repairing the violation store is disabled (enable by configuration %s.%s=true)",
+                                ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+                    }
+                    boolean changed = repair(scan, loaded);
+                    if (changed) {
+                        writeRulesTo(storedRulesPath, loaded);
+                    }
+                }
+            }
+            storedRules = loaded;
+        } catch (StoreInitializationFailedException e) {
+            if (indexCreated) {
+                deleteCreatedIndex();
+            }
+            throw e;
+        } catch (RuntimeException e) {
+            if (indexCreated) {
+                deleteCreatedIndex();
+            }
+            throw e;
+        }
+    }
+
+    private void deleteCreatedIndex() {
+        try {
+            Files.deleteIfExists(storedRulesPath);
+        } catch (IOException e) {
+            log.debug("Could not remove an index created during a rejected initialization", e);
+        }
+    }
+
+    private IntegrityMode parseIntegrity(String value) {
+        if ("ignore".equals(value)) {
+            return IntegrityMode.IGNORE;
+        }
+        if ("repair".equals(value)) {
+            if (!Boolean.parseBoolean("true")) { // Keeps this branch visibly tied to the exact accepted value.
+                throw new AssertionError();
+            }
+            return IntegrityMode.REPAIR;
+        }
+        if ("fail".equals(value)) {
+            return IntegrityMode.FAIL;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid %s '%s'; accepted values are repair, fail and ignore", INTEGRITY_PROPERTY_NAME, value));
+    }
+
+    private void configureFileNameStrategy(Properties properties) {
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (constructorStrategy != null) {
+            if (configured != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured when a RuleViolationFileNameStrategy was supplied to the constructor", FILE_NAMES_PROPERTY_NAME));
+            }
+            fileNameMode = FileNameMode.CONSTRUCTOR;
+            ruleViolationFileNameStrategy = constructorStrategy;
+            return;
+        }
+
+        if (configured == null || "random".equals(configured)) {
+            fileNameMode = FileNameMode.RANDOM;
+            ruleViolationFileNameStrategy = null;
+        } else if ("description".equals(configured)) {
+            fileNameMode = FileNameMode.DESCRIPTION;
+            ruleViolationFileNameStrategy = null;
+        } else {
+            fileNameMode = FileNameMode.CONSTRUCTOR;
+            ruleViolationFileNameStrategy = instantiateStrategy(configured);
+        }
+    }
+
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> strategyClass = Class.forName(className);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s does not implement %s", className, RuleViolationFileNameStrategy.class.getName()));
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot instantiate %s as a RuleViolationFileNameStrategy with a public no-argument constructor", className), e);
+        }
+    }
+
+    private static Object lockFor(String path) {
+        return LOCKS_BY_PATH.computeIfAbsent(path, ignored -> new Object());
+    }
+
+    @Override
+    public synchronized boolean contains(ArchRule rule) {
+        synchronized (lockFor(lockKey)) {
+            refreshRules();
+            return storedRules.containsKey(normalize(rule.getDescription()));
+        }
+    }
+
+    @Override
+    public synchronized void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (lockFor(lockKey)) {
+            refreshRules();
+            String description = normalize(rule.getDescription());
+            String existingFileName = storedRules.getProperty(description);
+
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                if (existingFileName == null) {
+                    return;
+                }
+                if (!isSharedByAnotherEntry(description, existingFileName)) {
+                    deleteEntryFileForSave(existingFileName);
+                }
+                storedRules.remove(description);
+                writeRulesTo(storedRulesPath, storedRules);
+                return;
+            }
+
+            if (violations.isEmpty() && existingFileName == null) {
+                return;
+            }
+
+            String fileName = existingFileName;
+            if (fileName == null) {
+                fileName = createNewFileName(description);
+            }
+            validateName(fileName, "saving rule '" + description + "'");
+            Path target = directPathFor(fileName);
+            if (target == null || target.equals(storedRulesPath)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write violation file '%s' outside the store folder or over %s", fileName, STORED_RULES_FILE_NAME));
+            }
+
+            boolean targetExists = pathExists(target);
+            if (targetExists) {
+                if (existingFileName == null || !isRegularDirectFile(target)) {
+                    throw new StoreUpdateFailedException(String.format(
+                            "Refusing to overwrite violation file '%s' which is not recorded by this rule", fileName));
+                }
+            }
+
+            boolean newEntry = existingFileName == null;
+            writeViolationFile(target, violations, targetExists);
+            if (newEntry) {
+                storedRules.setProperty(description, normalize(fileName));
+                try {
+                    writeRulesTo(storedRulesPath, storedRules);
+                } catch (RuntimeException e) {
+                    try {
+                        Files.deleteIfExists(target);
+                    } catch (IOException ignored) {
+                        // Preserve the original failure. The index still does not record this file.
+                    }
+                    throw e;
+                }
+            }
+        }
+    }
+
+    @Override
+    public synchronized List<String> getViolations(ArchRule rule) {
+        synchronized (lockFor(lockKey)) {
+            refreshRules();
+            String fileName = storedRules.getProperty(normalize(rule.getDescription()));
+            checkArgument(fileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(fileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private void refreshRules() {
+        if (storedRulesPath == null || !isRegularDirectFile(storedRulesPath)) {
+            throw new StoreReadException(new IOException("The violation store has not been initialized or its index is invalid"));
+        }
+        storedRules = loadRulesFrom(storedRulesPath);
+    }
+
+    private String createNewFileName(String description) {
+        if (fileNameMode == FileNameMode.RANDOM) {
+            String candidate;
+            do {
+                candidate = UUID.randomUUID().toString();
+            } while (pathExists(directPathFor(candidate)) || recordsFileName(candidate));
+            return candidate;
+        }
+        return nameFromStrategy(description);
+    }
+
+    private String nameFromStrategy(String description) {
+        String result;
+        if (fileNameMode == FileNameMode.DESCRIPTION) {
+            result = descriptionFileName(description);
+        } else {
+            try {
+                result = ruleViolationFileNameStrategy.createRuleFileName(description);
+            } catch (RuntimeException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        validateName(result, "creating a violation file name for rule '" + description + "'");
+        return result;
+    }
+
+    private String descriptionFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String selectedWord = null;
+        while (matcher.find()) {
+            String word = matcher.group(1);
+            if (selectedWord == null || word.length() > selectedWord.length()) {
+                selectedWord = word;
+            }
+        }
+        String hash = sha256(description);
+        return (selectedWord == null ? "rule" : selectedWord) + "-" + hash;
+    }
+
+    private String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte item : digest) {
+                result.append(String.format("%02x", item & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private void validateName(String name, String context) {
+        if (name == null || name.trim().isEmpty()) {
+            throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no name while " + context);
+        }
+    }
+
+    private IntegrityScan inspect(Properties properties) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String fileName = properties.getProperty(description);
+            Entry entry = new Entry(description, fileName);
+            entries.add(entry);
+            inspectEntry(entry);
+        }
+        entries.sort(Comparator.comparing(entry -> entry.description));
+
+        markSharedEntries(entries);
+        Map<String, Integer> derivedNameCounts = new HashMap<>();
+        for (Entry entry : entries) {
+            if (fileNameMode != FileNameMode.RANDOM) {
+                entry.derivedName = nameFromStrategyForInspection(entry.description);
+                if (entry.derivedName != null) {
+                    derivedNameCounts.put(entry.derivedName, derivedNameCounts.getOrDefault(entry.derivedName, 0) + 1);
+                }
+            }
+        }
+        for (Entry entry : entries) {
+            if (entry.derivedName != null) {
+                entry.misplaced = !entry.fileName.equals(entry.derivedName);
+                entry.colliding = derivedNameCounts.get(entry.derivedName) > 1;
+                if (entry.misplaced) {
+                    Path derivedPath = directPathFor(entry.derivedName);
+                    entry.occupied = derivedPath == null || derivedPath.equals(storedRulesPath)
+                            || pathExists(derivedPath) || recordsFileNameExcept(entry.derivedName, entry.description);
+                }
+            }
+        }
+
+        List<Path> unownedFiles = findUnownedFiles(entries);
+        return new IntegrityScan(entries, unownedFiles);
+    }
+
+    private String nameFromStrategyForInspection(String description) {
+        try {
+            String result = fileNameMode == FileNameMode.DESCRIPTION
+                    ? descriptionFileName(description)
+                    : ruleViolationFileNameStrategy.createRuleFileName(description);
+            if (result == null || result.trim().isEmpty()) {
+                throw new StoreInitializationFailedException(
+                        "RuleViolationFileNameStrategy returned no name while inspecting rule '" + description + "'");
+            }
+            return result;
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (RuntimeException e) {
+            throw new StoreInitializationFailedException(
+                    "Could not derive a violation file name while inspecting rule '" + description + "'", e);
+        }
+    }
+
+    private void inspectEntry(Entry entry) {
+        if (entry.fileName == null) {
+            entry.broken = true;
+            return;
+        }
+        Path namedPath = directPathFor(entry.fileName);
+        entry.namedPath = namedPath;
+        if (namedPath == null || namedPath.equals(storedRulesPath)) {
+            entry.broken = true;
+            return;
+        }
+        if (!pathExists(namedPath)) {
+            entry.broken = true;
+            return;
+        }
+        try {
+            entry.realPath = namedPath.toRealPath();
+            entry.realFile = Files.isRegularFile(entry.realPath, LinkOption.NOFOLLOW_LINKS);
+            entry.validFile = entry.realFile && storeFolderRealPath.equals(entry.realPath.getParent());
+            if (!entry.validFile) {
+                entry.broken = true;
+                return;
+            }
+            String contents = new String(toByteArray(namedPath.toFile()), UTF_8);
+            entry.resolved = containsNoViolation(contents);
+        } catch (IOException e) {
+            entry.broken = true;
+        }
+    }
+
+    private boolean containsNoViolation(String contents) {
+        // A CR is deliberately not treated as a separator while reading a violation: it can be part of its text.
+        // For integrity, however, a file made solely from any accepted line-break spelling is empty.
+        if (contents.isEmpty()) {
+            return true;
+        }
+        for (int i = 0; i < contents.length(); i++) {
+            char character = contents.charAt(i);
+            if (character != '\n' && character != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private void markSharedEntries(List<Entry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry first = entries.get(i);
+                Entry second = entries.get(j);
+                if (first.fileName.equals(second.fileName) || sameFile(first.realPath, second.realPath)) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
