    private boolean containsNoViolation(String contents) {
        // A CR is deliberately not treated as a separator while reading a violation: it can be part of its text.
        // For integrity, however, a file made solely from any accepted line-break spelling is empty.
        if (contents.isEmpty()) {
            return true;
        }
        for (int i = 0; i < contents.length(); i++) {
            char character = contents.charAt(i);
            if (character != '\n' && character != '\r') {
                return false;
            }
        }
        return true;
    }

    private void markSharedEntries(List<Entry> entries) {
        for (int i = 0; i < entries.size(); i++) {
            for (int j = i + 1; j < entries.size(); j++) {
                Entry first = entries.get(i);
                Entry second = entries.get(j);
                if (first.fileName.equals(second.fileName) || sameFile(first.realPath, second.realPath)) {
                    first.shared = true;
                    second.shared = true;
                }
            }
        }
    }

